class ShellActivity : AppCompatActivity() {          // hosts the framework's handler
    private val vm: ShellViewModel by viewModels()
    override fun onCreate(s: Bundle?) {
        super.onCreate(s)
        val nav = findNavController(R.id.nav_host)   // the framework's registry
        vm.currentScreen.observe(this) { nav.navigate(it.destination, it.args) }   // switch
        lifecycleScope.launch {
            repeatOnLifecycle(Lifecycle.State.STARTED) {
                vm.model.collect { renderInto(nav.currentDestination) }   // sync
            }
        }
    }
}
